// 0.6.0-circuit: RiderLab circuit file "RLC1" parser (from Beta X H draft). Read-only, no heap.
// Little-endian, packed. Generated by make_circuit_bin.py. Origin (0,0) = ANCHOR = first valid fix of
// the outer mapping pass = start/finish. Points int16 in units of (unit_mm/1000) m (0.1 m -> +-3276.7 m).
//
//  off size field
//   0   4   magic "RLC1"
//   4   1   version (1)
//   5   1   flags  bit0: 1 = CCW (direction of travel while mapping), 0 = CW
//   6   2   unit_mm (100 = 0.1 m)
//   8   8   anchor_lat  (double, deg)      full precision
//  16   8   anchor_lon  (double, deg)
//  24   4   anchor_alt  (float, m, GNSS)
//  28   4   centerline_len_m (float)
//  32   4   start_heading_deg (float, compass, direction of travel at S/F) -> heading-up rotation
//  36   2   n_outer   38 2 n_inner   40 2 n_center   42 1 n_gates   43 1 n_sectors
//  44  24   name (utf-8, NUL-padded)
//  68   ..  outer[n_outer]  {int16 x_east, int16 y_north}   recording order, [0] = anchor
//       ..  inner[n_inner]  {int16 x, int16 y}              recording order, [0] abreast S/F
//       ..  center[n_center]{int16 x, int16 y}              [0] = S/F, distance along it = lap progress
//       ..  gates[n_gates]  {int16 ax,ay (inner end), bx,by (outer end), uint16 s_dm, uint8 kind}
//                            kind 0 = start/finish, 1 = sector boundary, 2 = micro-sector
//                            gates sorted by s; sector k (1-based) starts at the k-th kind<=1 gate
//   end 4   crc32 (zlib) of all previous bytes
#pragma once
#include <cstdint>
#include <cstring>
#include <cmath>

namespace riderlab {

struct CPt { int16_t x, y; };
struct CGate { CPt a, b; uint16_t s_dm; uint8_t kind; };

struct Circuit {
  static constexpr int kMaxEdge = 150, kMaxCenter = 200, kMaxGates = 64;
  double lat0 = 0, lon0 = 0; float alt0 = 0, lenM = 0, head0 = 0, unit = 0.1f;
  bool ccw = true; char name[25] = {};
  uint16_t nO = 0, nI = 0, nC = 0; uint8_t nG = 0, nSec = 0;
  CPt outer[kMaxEdge], inner[kMaxEdge], center[kMaxCenter]; CGate gate[kMaxGates];
  float cumS[kMaxCenter];            // metres along centerline, built at load
  float kx = 0, ky = 0;              // m per degree at anchor (same formula as generator)
  // ~ (150+150+200)*4 + 64*11 + 200*4 ≈ 3.5 KB static. No heap.

  void enu(double lat, double lon, float& x, float& y) const {
    x = (float)((lon - lon0) * kx); y = (float)((lat - lat0) * ky);
  }
  bool parse(const uint8_t* b, size_t n) {
    if (n < 72 || memcmp(b, "RLC1", 4) != 0 || b[4] != 1) return false;
    if (crc32(b, n - 4) != rd<uint32_t>(b + n - 4)) return false;
    ccw = b[5] & 1; unit = rd<uint16_t>(b + 6) / 1000.0f;
    lat0 = rd<double>(b + 8); lon0 = rd<double>(b + 16); alt0 = rd<float>(b + 24);
    lenM = rd<float>(b + 28); head0 = rd<float>(b + 32);
    nO = rd<uint16_t>(b + 36); nI = rd<uint16_t>(b + 38); nC = rd<uint16_t>(b + 40); nG = b[42]; nSec = b[43];
    memcpy(name, b + 44, 24); name[24] = 0;
    if (nO > kMaxEdge || nI > kMaxEdge || nC > kMaxCenter || nG > kMaxGates) return false;
    if (68 + 4 * (nO + nI + nC) + 11 * nG + 4 != n) return false;
    const uint8_t* p = b + 68;
    auto pts = [&](CPt* d, int m) { for (int i = 0; i < m; ++i, p += 4) { d[i].x = rd<int16_t>(p); d[i].y = rd<int16_t>(p + 2); } };
    pts(outer, nO); pts(inner, nI); pts(center, nC);
    for (int i = 0; i < nG; ++i, p += 11) {
      gate[i].a = {rd<int16_t>(p), rd<int16_t>(p + 2)}; gate[i].b = {rd<int16_t>(p + 4), rd<int16_t>(p + 6)};
      gate[i].s_dm = rd<uint16_t>(p + 8); gate[i].kind = p[10];
    }
    const double r = lat0 * M_PI / 180;
    ky = (float)(111132.92 - 559.82 * cos(2 * r) + 1.175 * cos(4 * r));
    kx = (float)(111412.84 * cos(r) - 93.5 * cos(3 * r));
    cumS[0] = 0;
    for (int i = 1; i < nC; ++i) cumS[i] = cumS[i - 1] + unit * hypotf(center[i].x - center[i - 1].x, center[i].y - center[i - 1].y);
    return true;
  }
  // lap progress: metres along the centerline from S/F (nearest segment; caller may pass a search hint)
  float progress(float x, float y, int& seg, float& dist) const {
    float best = 1e30f, sOut = 0;
    for (int i = 0; i < nC; ++i) {
      int j = (i + 1) % nC; float ax = center[i].x * unit, ay = center[i].y * unit;
      float dx = center[j].x * unit - ax, dy = center[j].y * unit - ay, l2 = dx * dx + dy * dy + 1e-9f;
      float t = ((x - ax) * dx + (y - ay) * dy) / l2; t = t < 0 ? 0 : (t > 1 ? 1 : t);
      float ex = ax + t * dx - x, ey = ay + t * dy - y, d2 = ex * ex + ey * ey;
      if (d2 < best) { best = d2; seg = i; sOut = cumS[i] + t * sqrtf(l2); }
    }
    dist = sqrtf(best); return sOut;
  }
  // track tangent heading (compass deg) at centerline segment -> wrong-way / heading sanity check
  float tangentDeg(int i) const {
    int j = (i + 1) % nC; return fmodf(atan2f(center[j].x - center[i].x, center[j].y - center[i].y) * 57.29578f + 360, 360);
  }
 private:
  template <class T> static T rd(const uint8_t* p) { T v; memcpy(&v, p, sizeof v); return v; }
  static uint32_t crc32(const uint8_t* d, size_t n) {
    uint32_t c = 0xFFFFFFFFu;
    for (size_t i = 0; i < n; ++i) { c ^= d[i]; for (int k = 0; k < 8; ++k) c = (c >> 1) ^ (0xEDB88320u & -(c & 1)); }
    return ~c;
  }
};

}  // namespace riderlab
